  &reftitle.examples;

   Exemplo de Pdo\Sqlite::setAuthorizer

    Apenas ações de leitura são permitidas na conexão. Os códigos das ações são expostos
    como constantes da classe SQLite3, o que exige que a
    extensão SQLite3 esteja disponível; caso contrário,
    seus valores inteiros podem ser usados diretamente.



<?php
$db = new Pdo\Sqlite('sqlite::memory:');
$db->exec('CREATE TABLE users (id, name)');

$db->setAuthorizer(function (int $action, ...$args) {
    return match ($action) {
        SQLite3::SELECT, SQLite3::READ => Pdo\Sqlite::OK,
        default => Pdo\Sqlite::DENY,
    };
});

var_dump($db->query('SELECT name FROM users') instanceof PDOStatement);

try {
    $db->exec('DROP TABLE users');
} catch (PDOException $e) {
    echo $e->getMessage(), "\n";
}
?>


